package org.genhttp.engine.shared.types

import org.genhttp.api.protocol.ByteString
import org.genhttp.api.protocol.Connection
import org.genhttp.api.protocol.KeyValueList
import org.genhttp.api.protocol.Response
import org.genhttp.api.protocol.ResponseBuilder
import org.genhttp.api.protocol.ResponseContent
import org.genhttp.api.protocol.ResponseStatus

/**
 * A response generated by a handler, reused for all requests of a connection (`Response` in GenHTTP).
 */
public class HttpResponse(private val builder: ResponseBuilder) : Response {

    private val _headers = EditableKeyValueList()

    override var status: ResponseStatus = ResponseStatus.NoContent

    override var mode: Connection = Connection.KeepAlive

    override var content: ResponseContent? = null

    override val headers: KeyValueList
        get() = _headers

    /**
     * The headers of the response, allowing them to be modified.
     */
    public val editableHeaders: EditableKeyValueList
        get() = _headers

    override fun rebuild(): ResponseBuilder = builder

    /**
     * Resets the response so it can be reused.
     */
    public fun reset() {
        status = ResponseStatus.NoContent
        mode = Connection.KeepAlive
        content = null
        _headers.clear()
    }

}
